import{_ as a,o as r,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Barriers between Ceph Development and Ceph Support","description":"","frontmatter":{"title":"Barriers between Ceph Development and Ceph Support","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph","containerization","cephadm","distributed storage","support workflow"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Barriers_between_Ceph_Development_and_Ceph_Support.md","filePath":"posts/2026/Barriers_between_Ceph_Development_and_Ceph_Support.md","lastUpdated":1780459816000}'),l={name:"posts/2026/Barriers_between_Ceph_Development_and_Ceph_Support.md"};function o(p,e,h,d,n,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h2 id="演讲背景" tabindex="-1">演讲背景 <a class="header-anchor" href="#演讲背景" aria-label="Permalink to &quot;演讲背景&quot;">​</a></h2><p>本次演讲由来自 Croyd 公司的 L2 Ceph 支持工程师 K. Gopalakrishnan 主讲。Croyd 成立于 2017 年，专注于简化 Ceph 的部署与管理，提供 Ceph 管理 UI，并向用户提供技术支持服务（support@croyd.io）。</p><h2 id="核心议题-从用户到开发者的-bug-修复流程" tabindex="-1">核心议题：从用户到开发者的 Bug 修复流程 <a class="header-anchor" href="#核心议题-从用户到开发者的-bug-修复流程" aria-label="Permalink to &quot;核心议题：从用户到开发者的 Bug 修复流程&quot;">​</a></h2><h3 id="理想流程" tabindex="-1">理想流程 <a class="header-anchor" href="#理想流程" aria-label="Permalink to &quot;理想流程&quot;">​</a></h3><p>演讲者以&quot;故事&quot;的形式逐层拆解了 Ceph 生态中各角色的工作流程：</p><p><strong>用户视角</strong>：用户在 Ceph 集群上发现 bug → 联系支持团队 → 支持团队联系开发者 → 修复被开发、测试、打包 → 用户收到修复。</p><p><strong>开发者视角</strong>：</p><ol><li><code>git clone</code> Ceph 仓库，在新分支上 checkout</li><li>编写修复代码，经过 review 和迭代</li><li>通过 <code>vstart.sh</code> 进行构建测试</li><li>提交最终 commit，生成 patch set或 PR</li><li>将修复 backport 到 release/stable 分支</li><li>通过独立的打包和发布渠道完成部署</li></ol><p><strong>Maintainer 视角</strong>（以 Proxmox、SUSE、Ubuntu 等下游发行商为例）：</p><ul><li>获取 bug 通知和 patch</li><li>在自有基础设施中重新构建软件包</li><li>通过自有渠道推送给用户</li></ul><p>在基于软件包（package-based）的部署模式下，上述流程运转良好：用户无需自建基础设施，无需等待新版本发布，修复交付快速高效。</p><h2 id="核心问题-容器化部署带来的新挑战" tabindex="-1">核心问题：容器化部署带来的新挑战 <a class="header-anchor" href="#核心问题-容器化部署带来的新挑战" aria-label="Permalink to &quot;核心问题：容器化部署带来的新挑战&quot;">​</a></h2><h3 id="背景转变" tabindex="-1">背景转变 <a class="header-anchor" href="#背景转变" aria-label="Permalink to &quot;背景转变&quot;">​</a></h3><p>Ceph 正在从 package-based 部署向 container-based 部署迁移，cephadm 已成为官方推荐的标准部署方式，容器镜像来源于 quay.io。</p><h3 id="官方容器构建流程" tabindex="-1">官方容器构建流程 <a class="header-anchor" href="#官方容器构建流程" aria-label="Permalink to &quot;官方容器构建流程&quot;">​</a></h3><p>官方流程为：源代码 → RPM 包 → 上传至 yum repo → 构建容器镜像 → 交付至用户集群。</p><p>构建工具链：</p><ul><li><code>build_with_container.py</code>：Python 脚本，负责整体构建流程</li><li><code>container file</code> + <code>build.sh</code>：实际调用 podman 构建容器</li><li>环境变量控制构建行为，其中关键变量为 <code>CUSTOM_CEPH_REPO_URL</code></li></ul><h3 id="问题一-无法从本地-rpm-构建运行时镜像" tabindex="-1">问题一：无法从本地 RPM 构建运行时镜像 <a class="header-anchor" href="#问题一-无法从本地-rpm-构建运行时镜像" aria-label="Permalink to &quot;问题一：无法从本地 RPM 构建运行时镜像&quot;">​</a></h3><p><code>build_with_container.py</code> 在 RPM 构建步骤完成后即停止，不会继续生成容器镜像，且不报错，导致支持团队无法将本地 patch 打入容器。</p><p>一年前，<code>CUSTOM_CEPH_REPO_URL</code> 环境变量根本不存在，支持团队完全没有办法从自定义 repo 拉取 RPM 来构建容器。感谢 John Mulligan 贡献了该变量，但目前该 patch 仅存在于 main 分支，尚未 backport 到 squid 和 tentacle 分支。</p><h3 id="问题二-无法将容器镜像导出为本地-tarball" tabindex="-1">问题二：无法将容器镜像导出为本地 tarball <a class="header-anchor" href="#问题二-无法将容器镜像导出为本地-tarball" aria-label="Permalink to &quot;问题二：无法将容器镜像导出为本地 tarball&quot;">​</a></h3><p>在 air-gapped（离线隔离）环境中，无法从外部 registry 拉取镜像，必须能够将镜像导出为 tarball 并分发到所有 cephadm 节点。目前官方构建流程不支持此功能。</p><h3 id="问题三-cephadm-的-registry-校验阻碍本地镜像使用" tabindex="-1">问题三：cephadm 的 registry 校验阻碍本地镜像使用 <a class="header-anchor" href="#问题三-cephadm-的-registry-校验阻碍本地镜像使用" aria-label="Permalink to &quot;问题三：cephadm 的 registry 校验阻碍本地镜像使用&quot;">​</a></h3><p>即使完成了本地镜像构建并推送到本地 registry，cephadm 的 orchestrator 也会因 validation 检查而阻止升级：</p><ul><li>本地镜像没有 repo digest</li><li>需要手动设置 <code>ceph_use_repo_digest = false</code></li><li>若使用 HTTP（无 TLS），还需设置 <code>registry_insecure = true</code></li></ul><h3 id="当前支持团队的临时工作流-步骤繁琐" tabindex="-1">当前支持团队的临时工作流（步骤繁琐） <a class="header-anchor" href="#当前支持团队的临时工作流-步骤繁琐" aria-label="Permalink to &quot;当前支持团队的临时工作流（步骤繁琐）&quot;">​</a></h3><ol><li>修复 curl 问题，确保所有包来自本地而非 shaman.ceph.com 或 download.ceph.com</li><li>Backport John Mulligan 的 <code>CUSTOM_CEPH_REPO_URL</code> patch</li><li>使用 <code>build_with_container.py</code> 构建 RPM</li><li>将 RPM 放入自定义 repo 并配置 repo URL</li><li>提供一个空的 dummy credentials文件（构建系统要求）</li><li>使用 <code>build.sh</code> 构建容器镜像</li><li>搭建自定义基础设施并推送镜像</li><li>向客户解释如何从自定义地址拉取镜像</li></ol><p>这一流程步骤过多，对支持团队造成了极大负担。</p><h2 id="解决方向与进展" tabindex="-1">解决方向与进展 <a class="header-anchor" href="#解决方向与进展" aria-label="Permalink to &quot;解决方向与进展&quot;">​</a></h2><h3 id="正在推进的工作" tabindex="-1">正在推进的工作 <a class="header-anchor" href="#正在推进的工作" aria-label="Permalink to &quot;正在推进的工作&quot;">​</a></h3><p>演讲者的同事已提交一系列 patch，目标是实现<strong>一条命令完成完整的本地容器镜像构建</strong>（包含所有 patch）。目前该方案仍处于 draft 阶段，需要进一步完善，但演讲者已验证其可行性。</p><h3 id="期望目标" tabindex="-1">期望目标 <a class="header-anchor" href="#期望目标" aria-label="Permalink to &quot;期望目标&quot;">​</a></h3><ol><li>将完整的构建流程文档化，发布至 docs.ceph.com</li><li>支持在不执行大量额外步骤的情况下，对旧版本 Ceph release 同样适用</li><li>部分支持厂商已有内部维护的自定义 container registry（预置关键 bug fix），希望这些经验能够上游化并形成文档</li></ol><h2 id="总结与展望" tabindex="-1">总结与展望 <a class="header-anchor" href="#总结与展望" aria-label="Permalink to &quot;总结与展望&quot;">​</a></h2><ul><li>容器化部署中 hotfix 交付困难的问题并非 Ceph 独有，是整个容器生态面临的共性挑战</li><li>从本地源码自动化构建容器镜像只是第一步</li><li>社区应共同努力，让用户能够在不等待正式 release 的情况下及时获得 bug 修复</li><li>减少支持团队与开发团队之间的流程壁垒，是提升 Ceph 生态整体健康度的关键</li></ul>',36)])])}const _=a(l,[["render",o]]);export{u as __pageData,_ as default};
